#!/bin/sh
# chat-bridge.sh — point Mc2Discord at the Discord channel.
#
# Mc2Discord needs two secrets in its own config: the bot token, and the id
# of the channel to bridge. Neither belongs in a public repo, so the repo
# holds this script instead. It reads the token from the bot's .env - the
# same .env the bot itself uses - and writes both values into the server's
# config/mc2discord.toml, which is generated by the mod on its first start.
#
# Usage:
#   ./scripts/chat-bridge.sh <live|dev> <channel-id>
#
# Run it once after the server has started with Mc2Discord installed, and
# again if the channel changes. It sets the token, the channel, and a few
# display settings, and leaves everything else alone, so re-running it is
# safe.
#
# The token can be overridden with CHAT_BRIDGE_TOKEN, which is useful for
# using a separate bot for the bridge. By default it uses the same bot the
# Discord bot runs as, which is fine: Discord allows more than one
# connection per application.

set -eu

REPO_ROOT=$(git -C "$(dirname "$0")" rev-parse --show-toplevel)
cd "$REPO_ROOT"

ENV=${1:-}
CHANNEL=${2:-}

case "$ENV" in
live | dev) ;;
*)
	echo "usage: $0 <live|dev> <channel-id>" >&2
	exit 2
	;;
esac

case "$CHANNEL" in
'' | *[!0-9]*)
	echo "usage: $0 <live|dev> <channel-id> (a number)" >&2
	exit 2
	;;
esac

ENV_FILE="minecraft/env/$ENV/env.conf"
[ -f "$ENV_FILE" ] || {
	echo "no environment config at $ENV_FILE" >&2
	exit 1
}

SERVER_ID=$(sed -n 's/^SERVER_ID=//p' "$ENV_FILE")
[ -n "$SERVER_ID" ] || {
	echo "$ENV_FILE has no SERVER_ID" >&2
	exit 1
}

TOKEN=${CHAT_BRIDGE_TOKEN:-}
if [ -z "$TOKEN" ]; then
	TOKEN_FILE=/opt/honeybee-discord-bot/.env
	[ -r "$TOKEN_FILE" ] || {
		echo "cannot read $TOKEN_FILE; set CHAT_BRIDGE_TOKEN instead" >&2
		exit 1
	}
	TOKEN=$(sed -n 's/^DISCORD_TOKEN=//p' "$TOKEN_FILE" | head -1)
fi
[ -n "$TOKEN" ] || {
	echo "no Discord token found" >&2
	exit 1
}

CONFIG="/opt/crafty/servers/$SERVER_ID/config/mc2discord.toml"
if ! sudo test -f "$CONFIG"; then
	echo "$CONFIG does not exist yet - start the server once with Mc2Discord" >&2
	exit 1
fi

sudo python3 - "$CONFIG" "$TOKEN" "$CHANNEL" <<'PY'
import re
import sys

path, token, channel = sys.argv[1], sys.argv[2], sys.argv[3]
with open(path, encoding="utf-8") as fh:
    lines = fh.read().splitlines()


def fail(what):
    sys.exit(f"could not find {what} in {path}")


# The token lives under [General]. It is the only key of that name there,
# so a simple search does the job.
for i, line in enumerate(lines):
    if line.startswith("\ttoken = "):
        lines[i] = f'\ttoken = "{token}"'
        break
else:
    fail("the token setting")

# The channel is the first id inside [Channels]. The Commands permission
# block has an id too, so this is anchored to the channel block rather
# than to the file.
start = next((i for i, l in enumerate(lines) if l.strip() == "[[Channels.Channel]]"), None)
if start is None:
    fail("the channel block")
for i in range(start, len(lines)):
    if lines[i].startswith("\t\tid = "):
        lines[i] = f"\t\tid = {channel}"
        break
    if lines[i].startswith("\t[[") and i > start:
        fail("the channel id")
else:
    fail("the channel id")

# Chat both ways, plus join/leave/death notices. Not "command": the
# console should not be runnable from a chat channel.
for i in range(start, len(lines)):
    if lines[i].startswith("\t\tsubscriptions = "):
        lines[i] = '\t\tsubscriptions = ["chat", "info"]'
        break
    if lines[i].startswith("\t[[") and i > start:
        fail("the subscriptions")
else:
    fail("the subscriptions")

# Player heads would be fetched from mc-heads.net, which hands a third
# party our players' UUIDs for nothing the map does not already show. The
# bot's own avatar is used instead.
for i, line in enumerate(lines):
    if line.startswith("\twebhook_avatar_api = "):
        lines[i] = '\twebhook_avatar_api = ""'
        break

# The /discord command in game should give the real invitation.
for i, line in enumerate(lines):
    if line.startswith("\tdiscord_text = "):
        lines[i] = '\tdiscord_text = "Join the Discord: https://discord.gg/TsBmAGPtMG"'
    elif line.startswith("\tdiscord_link = "):
        lines[i] = '\tdiscord_link = "https://discord.gg/TsBmAGPtMG"'

with open(path, "w", encoding="utf-8") as fh:
    fh.write("\n".join(lines) + "\n")
print(f"wrote the token and channel {channel} to {path}")
PY

echo "        (restarting the mod so it picks the settings up)"
./scripts/crafty.sh cmd "$SERVER_ID" "mc2discord restart" >/dev/null 2>&1 || {
	echo "could not reach the server console; run 'mc2discord restart' in game" >&2
	exit 1
}
echo "done - check with:"
echo "  ./scripts/crafty.sh cmd $SERVER_ID \"mc2discord status\""
